import subprocess as sp, os, sys
for args in [["--check","c1.txt"],["--check","cfail.txt"],["--check","cbad.txt"],["--check","nonexistent"],["--raw","foo.txt"],["--raw","--length","10000","foo.txt"]]:
    with open("/dev/full","wb") as full:
        p=sp.run(["/workspace/executable"]+args,cwd="/tmp/t2",stdout=sp.PIPE,stderr=full,stdin=sp.DEVNULL,timeout=3)
        print("stderr devfull",args,p.returncode,p.stdout)
def closed_fd(args, fdno):
    pid=os.fork()
    if pid==0:
        # redirect other to /dev/null? stderr keep to pipe? Child inherits python stderr (terminal captured in docker?). Just close target, redirect other to devnull for neat
        devnull=os.open("/dev/null",os.O_WRONLY)
        if fdno==1: os.dup2(devnull,2)
        else: os.dup2(devnull,1)
        os.close(fdno)
        os.chdir("/tmp/t2")
        os.execv("/workspace/executable",["b3sum"]+args)
    pid2,st=os.waitpid(pid,0)
    print(f"closed fd{fdno}",args,os.waitstatus_to_exitcode(st))
for a in [["--help"],["--version"],["foo.txt"],["--raw","foo.txt"],["--check","c1.txt"],["--unknown"],["missing"]]:
    closed_fd(a,1)
for a in [["--help"],["foo.txt"],["--unknown"],["missing"],["--keyed","foo.txt"]]:
    closed_fd(a,2)
