def jaro(a,b):
    if a==b:return 1.
    la,lb=len(a),len(b)
    if not la or not lb:return 0.
    md=max(la,lb)//2-1; md=max(md,0)
    af=[0]*la; bf=[0]*lb; m=0
    for i,ch in enumerate(a):
      for j in range(max(0,i-md),min(i+md+1,lb)):
        if not bf[j] and b[j]==ch: af[i]=bf[j]=1;m+=1;break
    if not m:return 0.
    k=t=0
    for i,ch in enumerate(a):
      if af[i]:
        while not bf[k]:k+=1
        if ch!=b[k]:t+=1
        k+=1
