const MSG_PERMUTATION: [usize; 16] = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8];

#[inline(always)]
fn g(state: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, mx: u32, my: u32) {
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(mx);
    state[d] = (state[d] ^ state[a]).rotate_right(16);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(12);
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(my);
    state[d] = (state[d] ^ state[a]).rotate_right(8);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(7);
}

#[inline(always)]
fn round(state: &mut [u32; 16], m: &[u32; 16]) {
    g(state, 0, 4, 8, 12, m[0], m[1]);
    g(state, 1, 5, 9, 13, m[2], m[3]);
    g(state, 2, 6, 10, 14, m[4], m[5]);
    g(state, 3, 7, 11, 15, m[6], m[7]);
    g(state, 0, 5, 10, 15, m[8], m[9]);
    g(state, 1, 6, 11, 12, m[10], m[11]);
    g(state, 2, 7, 8, 13, m[12], m[13]);
    g(state, 3, 4, 9, 14, m[14], m[15]);
}

#[inline(always)]
fn permute(m: &mut [u32; 16]) {
    let old = *m;
    for i in 0..16 {
        m[i] = old[MSG_PERMUTATION[i]];
    }
}

fn words_from_block(block: &[u8; BLOCK_LEN]) -> [u32; 16] {
    let mut words = [0u32; 16];
    for i in 0..16 {
        words[i] = u32::from_le_bytes([
            block[i * 4],
            block[i * 4 + 1],
            block[i * 4 + 2],
            block[i * 4 + 3],
        ]);
    }
    words
}

fn words_from_key(key: &[u8; KEY_LEN]) -> [u32; 8] {
    let mut words = [0u32; 8];
    for i in 0..8 {
        words[i] = u32::from_le_bytes([
            key[i * 4],
            key[i * 4 + 1],
            key[i * 4 + 2],
            key[i * 4 + 3],
        ]);
    }
    words
}

fn compress(
    cv: &[u32; 8],
    block: &[u8; BLOCK_LEN],
    counter: u64,
    block_len: u32,
    flags: u32,
) -> [u32; 16] {
    let mut msg = words_from_block(block);
    let mut state = [
        cv[0], cv[1], cv[2], cv[3], cv[4], cv[5], cv[6], cv[7],
        IV[0], IV[1], IV[2], IV[3],
        counter as u32,
        (counter >> 32) as u32,
        block_len,
        flags,
    ];
    for r in 0..7 {
        round(&mut state, &msg);
        if r != 6 {
            permute(&mut msg);
        }
    }
    let mut out = [0u32; 16];
    for i in 0..8 {
        out[i] = state[i] ^ state[i + 8];
        out[i + 8] = state[i + 8] ^ cv[i];
    }
    out
}

fn first8(words: [u32; 16]) -> [u32; 8] {
    let mut cv = [0u32; 8];
    cv.copy_from_slice(&words[..8]);
    cv
}

#[derive(Clone)]
pub struct Output {
    input_cv: [u32; 8],
    block: [u8; BLOCK_LEN],
    counter: u64,
    block_len: u32,
    flags: u32,
}

impl Output {
    fn chaining_value(&self) -> [u32; 8] {
        first8(compress(
            &self.input_cv,
            &self.block,
            self.counter,
            self.block_len,
            self.flags,
        ))
    }

    fn root_block(&self, output_counter: u64) -> [u8; BLOCK_LEN] {
        let words = compress(
            &self.input_cv,
            &self.block,
            output_counter,
            self.block_len,
            self.flags | ROOT,
        );
        let mut out = [0u8; BLOCK_LEN];
        for i in 0..16 {
            out[i * 4..i * 4 + 4].copy_from_slice(&words[i].to_le_bytes());
        }
        out
    }

    pub fn xof_reader(&self, seek: u64) -> XofReader {
        XofReader {
            output: self.clone(),
            block_counter: seek / BLOCK_LEN as u64,
            block: [0; BLOCK_LEN],
            pos: (seek % BLOCK_LEN as u64) as usize,
            have_block: false,
        }
    }

    pub fn fill(&self, seek: u64, out: &mut [u8]) {
        let mut reader = self.xof_reader(seek);
        let _ = reader.read_exact(out);
    }
}

pub struct XofReader {
    output: Output,
    block_counter: u64,
    block: [u8; BLOCK_LEN],
    pos: usize,
    have_block: bool,
}

impl Read for XofReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if buf.is_empty() {
            return Ok(0);
        }
        let mut written = 0;
        while written < buf.len() {
            if !self.have_block || self.pos >= BLOCK_LEN {
                self.block = self.output.root_block(self.block_counter);
                self.block_counter = self.block_counter.wrapping_add(1);
                if self.have_block {
                    self.pos = 0;
                }
                // On the very first block, `pos` may have been set by
                // a nonzero seek offset; on later blocks it has just
                // been reset above.
                self.have_block = true;
            }
            let avail = BLOCK_LEN - self.pos;
            let take = avail.min(buf.len() - written);
            buf[written..written + take]
                .copy_from_slice(&self.block[self.pos..self.pos + take]);
            self.pos += take;
            written += take;
        }
        Ok(written)
    }
}

#[derive(Clone)]
struct ChunkState {
    cv: [u32; 8],
    chunk_counter: u64,
    buf: [u8; BLOCK_LEN],
    buf_len: u8,
    blocks_compressed: u8,
    flags: u32,
}

impl ChunkState {
    fn new(key: [u32; 8], chunk_counter: u64, flags: u32) -> Self {
        Self {
            cv: key,
            chunk_counter,
            buf: [0; BLOCK_LEN],
            buf_len: 0,
            blocks_compressed: 0,
            flags,
        }
    }

    fn len(&self) -> usize {
        self.blocks_compressed as usize * BLOCK_LEN + self.buf_len as usize
    }

    fn start_flag(&self) -> u32 {
        if self.blocks_compressed == 0 {
            CHUNK_START
        } else {
            0
        }
    }

    fn update(&mut self, mut input: &[u8]) {
        while !input.is_empty() {
            if self.buf_len as usize == BLOCK_LEN {
                self.cv = first8(compress(
                    &self.cv,
                    &self.buf,
                    self.chunk_counter,
                    BLOCK_LEN as u32,
                    self.flags | self.start_flag(),
                ));
                self.blocks_compressed += 1;
                self.buf = [0; BLOCK_LEN];
                self.buf_len = 0;
            }
            let want = BLOCK_LEN - self.buf_len as usize;
            let take = want.min(input.len());
            self.buf[self.buf_len as usize..self.buf_len as usize + take]
                .copy_from_slice(&input[..take]);
            self.buf_len += take as u8;
            input = &input[take..];
        }
    }

    fn output(&self) -> Output {
        Output {
            input_cv: self.cv,
            block: self.buf,
            counter: self.chunk_counter,
            block_len: self.buf_len as u32,
            flags: self.flags | self.start_flag() | CHUNK_END,
        }
    }
}

fn parent_output(
    left_cv: [u32; 8],
    right_cv: [u32; 8],
    key: [u32; 8],
    flags: u32,
) -> Output {
    let mut block = [0u8; BLOCK_LEN];
    for i in 0..8 {
        block[i * 4..i * 4 + 4].copy_from_slice(&left_cv[i].to_le_bytes());
        block[BLOCK_LEN / 2 + i * 4..BLOCK_LEN / 2 + i * 4 + 4]
            .copy_from_slice(&right_cv[i].to_le_bytes());
    }
    Output {
        input_cv: key,
        block,
        counter: 0,
        block_len: BLOCK_LEN as u32,
        flags: flags | PARENT,
    }
}

#[derive(Clone)]
pub struct Hasher {
    key: [u32; 8],
    flags: u32,
    chunk: ChunkState,
    cv_stack: Vec<[u32; 8]>,
}

impl Hasher {
    fn with_key_words(key: [u32; 8], flags: u32) -> Self {
        Self {
            key,
            flags,
            chunk: ChunkState::new(key, 0, flags),
            cv_stack: Vec::with_capacity(54),
        }
    }

    pub fn new() -> Self {
        Self::with_key_words(IV, 0)
    }

    pub fn new_keyed(key: &[u8; KEY_LEN]) -> Self {
        Self::with_key_words(words_from_key(key), KEYED_HASH)
    }

    pub fn new_derive_key(context: &str) -> Self {
        let mut context_hasher = Self::with_key_words(IV, DERIVE_KEY_CONTEXT);
        context_hasher.update(context.as_bytes());
        let mut context_key = [0u8; KEY_LEN];
        context_hasher.finalize_output().fill(0, &mut context_key);
        Self::with_key_words(words_from_key(&context_key), DERIVE_KEY_MATERIAL)
    }

    fn push_cv(&mut self, mut cv: [u32; 8], mut total_chunks: u64) {
        while total_chunks % 2 == 0 {
            let left = self.cv_stack.pop().expect("cv stack for subtree");
            cv = parent_output(left, cv, self.key, self.flags).chaining_value();
            total_chunks /= 2;
        }
        self.cv_stack.push(cv);
    }

    pub fn update(&mut self, mut input: &[u8]) {
        while !input.is_empty() {
            if self.chunk.len() == CHUNK_LEN {
                let chunk_cv = self.chunk.output().chaining_value();
                let total_chunks = self.chunk.chunk_counter + 1;
                self.push_cv(chunk_cv, total_chunks);
                self.chunk = ChunkState::new(self.key, total_chunks, self.flags);
            }
            let want = CHUNK_LEN - self.chunk.len();
            let take = want.min(input.len());
            self.chunk.update(&input[..take]);
            input = &input[take..];
        }
    }

    pub fn update_reader<R: Read>(&mut self, reader: &mut R) -> io::Result<()> {
        let mut buf = [0u8; 65536];
        loop {
            match reader.read(&mut buf) {
                Ok(0) => return Ok(()),
                Ok(n) => self.update(&buf[..n]),
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(e) => return Err(e),
            }
        }
    }

    pub fn finalize_output(&self) -> Output {
        let mut output = self.chunk.output();
        for i in (0..self.cv_stack.len()).rev() {
            output = parent_output(
                self.cv_stack[i],
                output.chaining_value(),
                self.key,
                self.flags,
            );
        }
        output
    }
}
