            ArgId::Help => "--help",
            ArgId::Version => "--version",
            ArgId::File => "[FILE]...",
        }
    }

    fn is_value_option(self) -> bool {
        matches!(
            self,
            ArgId::DeriveKey | ArgId::Length | ArgId::Seek | ArgId::NumThreads
        )
    }

    fn is_flag(self) -> bool {
        matches!(
