#[derive(Debug, Default)]
pub struct ParsedArgs {
    pub keyed: bool,
    pub derive_key: Option<String>,
    pub length: u64,
    pub length_explicit: bool,
    pub seek: u64,
    pub num_threads: Option<usize>,
