            "--no-names is implied. In this case, only a single input is allowed.",
        ],
    },
    HelpEntry {
        heading: &[("      ", false), ("--tag", true)],
        short_text: "Output BSD-style checksums: BLAKE3 ([FILE]) = [HASH]",
        long_paragraphs: &["Output BSD-style checksums: BLAKE3 ([FILE]) = [HASH]"],
    },
    HelpEntry {
        heading: &[("  ", false), ("-c", true), (", ", false), ("--check", true)],
        short_text: "Read BLAKE3 sums from the [FILE]s and check them",
        long_paragraphs: &["Read BLAKE3 sums from the [FILE]s and check them"],
    },
    HelpEntry {
        heading: &[("      ", false), ("--quiet", true)],
        short_text: "Skip printing OK for each checked file",
        long_paragraphs: &[
            "Skip printing OK for each checked file",
            "Must be used with --check.",
        ],
    },
    HelpEntry {
        heading: &[("  ", false), ("-h", true), (", ", false), ("--help", true)],
        short_text: "Print help (see more with '--help')",
        long_paragraphs: &["Print help (see a summary with '-h')"],
    },
    HelpEntry {
        heading: &[("  ", false), ("-V", true), (", ", false), ("--version", true)],
        short_text: "Print version",
        long_paragraphs: &["Print version"],
    },
];

fn wrap_words(
    first_prefix: &str,
    first_plain_len: usize,
    cont_indent: usize,
    width: usize,
    text: &str,
    out: &mut String,
) {
    let mut cur = String::from(first_prefix);
    let mut cur_len = first_plain_len;
    let mut have_word = false;
    for word in text.split(' ') {
        let wlen = word.chars().count();
        if !have_word {
            cur.push_str(word);
            cur_len += wlen;
            have_word = true;
        } else if cur_len + 1 + wlen <= width {
            cur.push(' ');
            cur.push_str(word);
            cur_len += 1 + wlen;
        } else {
            out.push_str(&cur);
            out.push('\n');
            cur = " ".repeat(cont_indent);
            cur.push_str(word);
            cur_len = cont_indent + wlen;
        }
    }
    out.push_str(&cur);
    out.push('\n');
}

fn render_long_paragraphs(entry: &HelpEntry, width: usize, out: &mut String) {
    for (i, para) in entry.long_paragraphs.iter().enumerate() {
        if i > 0 {
            out.push_str("          \n");
        }
        let indent = " ".repeat(10);
        wrap_words(&indent, 10, 10, width, para, out);
    }
}

fn next_line_mode(help_pos: usize, width: usize) -> bool {
    if width < help_pos {
        return false;
    }
    // Clap moves help to the next line when the help column would begin
    // past roughly 40% of the terminal width.
    help_pos * 5 > width * 2
}

fn render_short_entry(
    ctx: &Ctx,
    color: bool,
    entry: &HelpEntry,
    help_pos: usize,
    next_line: bool,
    width: usize,
    out: &mut String,
) {
    let plain = heading_plain(entry);
    let styled = heading_styled(ctx, color, entry);
    if next_line {
        out.push_str(&styled);
        out.push('\n');
        let indent = " ".repeat(10);
        wrap_words(&indent, 10, 10, width, entry.short_text, out);
    } else {
        let pad = help_pos.saturating_sub(plain.chars().count());
        let first = format!("{}{}", styled, " ".repeat(pad));
        wrap_words(&first, help_pos, help_pos, width, entry.short_text, out);
    }
}

fn render_help(ctx: &Ctx, long: bool) -> String {
    let color = ctx.color_out;
    let width = ctx.width;
    let mut out = String::new();
    out.push_str(&ctx.usage_generic(color));
    out.push_str("\n\n");
    out.push_str(&ctx.header(color, "Arguments:"));
    out.push('\n');
    if long {
        out.push_str(&heading_styled(ctx, color, &FILE_ENTRY));
        out.push('\n');
        render_long_paragraphs(&FILE_ENTRY, width, &mut out);
    } else {
        let help_pos = heading_plain(&FILE_ENTRY).chars().count() + 2;
        let nl = next_line_mode(help_pos, width);
        render_short_entry(ctx, color, &FILE_ENTRY, help_pos, nl, width, &mut out);
    }
    out.push('\n');
    out.push_str(&ctx.header(color, "Options:"));
    out.push('\n');
    if long {
        for (i, entry) in OPTIONS.iter().enumerate() {
            if i > 0 {
                out.push('\n');
            }
            out.push_str(&heading_styled(ctx, color, entry));
            out.push('\n');
            render_long_paragraphs(entry, width, &mut out);
        }
    } else {
        let longest = OPTIONS
            .iter()
            .map(|e| heading_plain(e).chars().count())
            .max()
            .unwrap_or(0);
        let help_pos = longest + 2;
        let nl = next_line_mode(help_pos, width);
        for entry in OPTIONS {
            render_short_entry(ctx, color, entry, help_pos, nl, width, &mut out);
        }
    }
    out
}
