use std::env;
use std::ffi::{OsStr, OsString};
use std::io::{self, IsTerminal, Write};
use std::os::unix::ffi::{OsStrExt, OsStringExt};
use std::path::{Path, PathBuf};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ArgId {
    Keyed,
    DeriveKey,
    Length,
    Seek,
    NumThreads,
    NoMmap,
    NoNames,
    Raw,
    Tag,
    Check,
    Quiet,
    Help,
    Version,
    File,
}

const OPTION_IDS: [ArgId; 13] = [
    ArgId::Keyed,
    ArgId::DeriveKey,
    ArgId::Length,
    ArgId::Seek,
    ArgId::NumThreads,
    ArgId::NoMmap,
    ArgId::NoNames,
    ArgId::Raw,
    ArgId::Tag,
    ArgId::Check,
    ArgId::Quiet,
    ArgId::Help,
    ArgId::Version,
];

impl ArgId {
    fn index(self) -> usize {
        match self {
            ArgId::Keyed => 0,
            ArgId::DeriveKey => 1,
            ArgId::Length => 2,
            ArgId::Seek => 3,
            ArgId::NumThreads => 4,
            ArgId::NoMmap => 5,
            ArgId::NoNames => 6,
            ArgId::Raw => 7,
            ArgId::Tag => 8,
            ArgId::Check => 9,
            ArgId::Quiet => 10,
            ArgId::Help => 11,
            ArgId::Version => 12,
            ArgId::File => 13,
        }
    }

    fn long_name(self) -> Option<&'static str> {
        Some(match self {
            ArgId::Keyed => "keyed",
            ArgId::DeriveKey => "derive-key",
            ArgId::Length => "length",
            ArgId::Seek => "seek",
            ArgId::NumThreads => "num-threads",
            ArgId::NoMmap => "no-mmap",
            ArgId::NoNames => "no-names",
            ArgId::Raw => "raw",
            ArgId::Tag => "tag",
            ArgId::Check => "check",
            ArgId::Quiet => "quiet",
            ArgId::Help => "help",
            ArgId::Version => "version",
            ArgId::File => return None,
        })
    }

    fn display(self) -> &'static str {
        match self {
            ArgId::Keyed => "--keyed",
            ArgId::DeriveKey => "--derive-key <CONTEXT>",
            ArgId::Length => "--length <LEN>",
            ArgId::Seek => "--seek <SEEK>",
            ArgId::NumThreads => "--num-threads <NUM>",
            ArgId::NoMmap => "--no-mmap",
            ArgId::NoNames => "--no-names",
            ArgId::Raw => "--raw",
            ArgId::Tag => "--tag",
            ArgId::Check => "--check",
            ArgId::Quiet => "--quiet",
            ArgId::Help => "--help",
            ArgId::Version => "--version",
            ArgId::File => "[FILE]...",
        }
    }

    fn is_value_option(self) -> bool {
        matches!(
            self,
            ArgId::DeriveKey | ArgId::Length | ArgId::Seek | ArgId::NumThreads
        )
    }

    fn is_flag(self) -> bool {
        matches!(
            self,
            ArgId::Keyed
                | ArgId::NoMmap
                | ArgId::NoNames
                | ArgId::Raw
                | ArgId::Tag
                | ArgId::Check
                | ArgId::Quiet
        )
    }
}

#[derive(Debug, Default)]
pub struct ParsedArgs {
    pub keyed: bool,
    pub derive_key: Option<String>,
    pub length: u64,
    pub length_explicit: bool,
    pub seek: u64,
    pub num_threads: Option<usize>,
    pub no_mmap: bool,
    pub no_names: bool,
    pub raw: bool,
    pub tag: bool,
    pub check: bool,
    pub quiet: bool,
    pub files: Vec<PathBuf>,
}

pub struct CliExit {
    text: String,
    code: i32,
    to_stdout: bool,
}

pub enum ParseOutcome {
    Args(ParsedArgs),
    Exit(CliExit),
}

pub fn handle_exit(exit: CliExit) -> ! {
    if exit.to_stdout {
        let mut out = io::stdout().lock();
        let _ = out.write_all(exit.text.as_bytes());
        let _ = out.flush();
    } else {
        let mut out = io::stderr().lock();
        let _ = out.write_all(exit.text.as_bytes());
        let _ = out.flush();
    }
    std::process::exit(exit.code)
}

// ---------- environment: terminal width and colour ----------

#[repr(C)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

fn ioctl_width(fd: i32) -> Option<usize> {
    let mut ws = Winsize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    let rc = unsafe { ioctl(fd, 0x5413, &mut ws as *mut Winsize) };
    if rc == 0 && ws.ws_col > 0 {
        Some(ws.ws_col as usize)
    } else {
        None
    }
}

fn terminal_width() -> usize {
    for fd in [1, 2, 0] {
        if let Some(w) = ioctl_width(fd) {
            return w.min(100);
        }
    }
    if let Some(v) = env::var_os("COLUMNS") {
        if let Some(s) = v.to_str() {
            if let Ok(w) = s.parse::<usize>() {
                return w.min(100);
            }
        }
    }
    100
}

fn env_present_nonempty(name: &str) -> bool {
    match env::var_os(name) {
        Some(v) => !v.is_empty(),
        None => false,
    }
}

fn env_equals(name: &str, value: &[u8]) -> Option<bool> {
    env::var_os(name).map(|v| v.as_os_str().as_bytes() == value)
}

fn color_enabled(is_tty: bool) -> bool {
    if env_present_nonempty("NO_COLOR") {
        return false;
    }
    if env_present_nonempty("CLICOLOR_FORCE") {
        return true;
    }
    if let Some(is_zero) = env_equals("CLICOLOR", b"0") {
        if is_zero {
            return false;
        }
        return is_tty;
    }
    if !is_tty {
        return false;
    }
    match env_equals("TERM", b"dumb") {
        Some(is_dumb) => !is_dumb,
        None => false,
    }
}

#[derive(Clone)]
struct Ctx {
    bin: String,
    width: usize,
    color_out: bool,
    color_err: bool,
}

impl Ctx {
    fn bold(&self, color: bool, s: &str) -> String {
        if color {
            format!("\x1b[1m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn header(&self, color: bool, s: &str) -> String {
        if color {
            format!("\x1b[1m\x1b[4m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn yellow(&self, color: bool, s: &str) -> String {
        if color {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn green(&self, color: bool, s: &str) -> String {
        if color {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn styled_usage_arg(&self, color: bool, id: ArgId) -> String {
        let disp = id.display();
        match disp.find(' ') {
            Some(pos) => format!("{}{}", self.bold(color, &disp[..pos]), &disp[pos..]),
            None => self.bold(color, disp),
        }
    }

    fn usage_generic(&self, color: bool) -> String {
        format!(
            "{} {} [OPTIONS] [FILE]...",
            self.header(color, "Usage:"),
            self.bold(color, &self.bin)
        )
    }

    /// `file_marker` is either "[FILE]..." or "<FILE>...".
    fn usage_list(&self, color: bool, options: &[ArgId], file_marker: &str) -> String {
        let mut s = format!(
            "{} {}",
            self.header(color, "Usage:"),
            self.bold(color, &self.bin)
        );
        for id in options {
            s.push(' ');
            s.push_str(&self.styled_usage_arg(color, *id));
        }
        s.push(' ');
        s.push_str(file_marker);
        s
    }

    fn usage_giant(&self, color: bool) -> String {
        format!(
            "{} {} <FILE|--keyed|--derive-key <CONTEXT>|--length <LEN>|--seek <SEEK>|--num-threads <NUM>|--no-mmap|--no-names|--raw|--tag|--check|--quiet>",
            self.header(color, "Usage:"),
            self.bold(color, &self.bin)
        )
    }

    fn error(&self, msg: String, tip: Option<String>, usage: Option<String>) -> CliExit {
        let color = self.color_err;
        let err_word = if color {
            "\x1b[1m\x1b[31merror:\x1b[0m".to_string()
        } else {
            "error:".to_string()
        };
        let mut s = format!("{} {}\n", err_word, msg);
        if let Some(t) = tip {
            s.push_str(&format!("\n  {}\n", t));
        }
        if let Some(u) = usage {
            s.push_str(&format!("\n{}\n", u));
        }
        s.push_str(&format!(
            "\nFor more information, try '{}'.\n",
            self.bold(color, "--help")
        ));
        CliExit {
            text: s,
            code: 2,
            to_stdout: false,
        }
    }
}
