    let color = ctx.color_out;
    let width = ctx.width;
    let mut out = String::new();
    out.push_str(&ctx.usage_generic(color));
    out.push_str("\n\n");
    out.push_str(&ctx.header(color, "Arguments:"));
    out.push('\n');
    if long {
        out.push_str(&heading_styled(ctx, color, &FILE_ENTRY));
        out.push('\n');
        render_long_paragraphs(&FILE_ENTRY, width, &mut out);
    } else {
        let help_pos = heading_plain(&FILE_ENTRY).chars().count() + 2;
        let nl = next_line_mode(help_pos, width);
        render_short_entry(ctx, color, &FILE_ENTRY, help_pos, nl, width, &mut out);
    }
    out.push('\n');
    out.push_str(&ctx.header(color, "Options:"));
    out.push('\n');
    if long {
        for (i, entry) in OPTIONS.iter().enumerate() {
            if i > 0 {
                out.push('\n');
            }
            out.push_str(&heading_styled(ctx, color, entry));
            out.push('\n');
            render_long_paragraphs(entry, width, &mut out);
        }
    } else {
        let longest = OPTIONS
            .iter()
            .map(|e| heading_plain(e).chars().count())
            .max()
            .unwrap_or(0);
        let help_pos = longest + 2;
        let nl = next_line_mode(help_pos, width);
        for entry in OPTIONS {
            render_short_entry(ctx, color, entry, help_pos, nl, width, &mut out);
        }
    }
    out
}
