// ---------- suggestions ----------

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a == b {
        return 1.0;
    }
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    let search_range = (a_len.max(b_len) / 2).saturating_sub(1);
    let mut a_flags = vec![false; a_len];
    let mut b_flags = vec![false; b_len];
    let mut matches = 0usize;
    for i in 0..a_len {
        let start = i.saturating_sub(search_range);
        let end = (i + search_range + 1).min(b_len);
        for j in start..end {
            if !b_flags[j] && a[i] == b[j] {
                a_flags[i] = true;
                b_flags[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for i in 0..a_len {
        if a_flags[i] {
            while !b_flags[k] {
                k += 1;
            }
            if a[i] != b[k] {
                transpositions += 1;
            }
            k += 1;
        }
    }
    let m = matches as f64;
    (m / a_len as f64 + m / b_len as f64 + (m - (transpositions / 2) as f64) / m) / 3.0
}

fn suggestion(name: &str) -> Option<ArgId> {
    let mut best: Option<(f64, ArgId)> = None;
    for id in OPTION_IDS {
        let cand = id.long_name().unwrap();
        let conf = jaro(name, cand);
        if conf > 0.7 {
            match best {
                Some((b, _)) if b > conf => {}
                // On ties the later candidate in declaration order
                // wins, mirroring a stable sort followed by popping
                // the greatest element.
                _ => best = Some((conf, id)),
            }
        }
    }
    best.map(|(_, id)| id)
}

// ---------- parsing ----------

enum Pending {
    Option { id: ArgId, value: Option<OsString> },
    Files { values: Vec<OsString> },
}

struct Parser {
    ctx: Ctx,
    args: ParsedArgs,
    pending: Option<Pending>,
    after_sep: bool,
    order: Vec<ArgId>,
    reacted: [usize; 14],
    value_counts: [usize; 14],
    file_seen: bool,
    any_flag_reacted: bool,
}

type PResult<T> = Result<T, CliExit>;

impl Parser {
    fn new(ctx: Ctx) -> Self {
        Self {
            ctx,
            args: ParsedArgs {
                length: 32,
                ..Default::default()
            },
            pending: None,
            after_sep: false,
            order: Vec::new(),
            reacted: [0; 14],
            value_counts: [0; 14],
            file_seen: false,
            any_flag_reacted: false,
        }
    }

    fn record_order(&mut self, id: ArgId) {
        if !self.order.contains(&id) {
            self.order.push(id);
        }
    }

    fn err_invalid_utf8(&self) -> CliExit {
        self.ctx.error(
            "invalid UTF-8 was detected in one or more arguments".to_string(),
            None,
            Some(self.ctx.usage_generic(self.ctx.color_err)),
        )
    }

    fn err_duplicate(&self, id: ArgId) -> CliExit {
        let color = self.ctx.color_err;
        self.ctx.error(
            format!(
                "the argument '{}' cannot be used multiple times",
                self.ctx.yellow(color, id.display())
            ),
            None,
            Some(self.ctx.usage_generic(color)),
        )
    }

    fn err_missing_value(&self, id: ArgId) -> CliExit {
        let color = self.ctx.color_err;
        self.ctx.error(
            format!(
                "a value is required for '{}' but none was supplied",
                self.ctx.yellow(color, id.display())
            ),
            None,
            None,
        )
    }

    fn validate_value(&mut self, id: ArgId, value: &OsString) -> PResult<()> {
        let color = self.ctx.color_err;
        let value_str = match value.to_str() {
            Some(s) => s,
            None => return Err(self.err_invalid_utf8()),
        };
        let err_for = |e: String| {
            self.ctx.error(
                format!(
                    "invalid value '{}' for '{}': {}",
                    self.ctx.yellow(color, value_str),
                    self.ctx.bold(color, id.display()),
                    e
                ),
                None,
                None,
            )
        };
        match id {
            ArgId::DeriveKey => {
                self.args.derive_key = Some(value_str.to_string());
            }
            ArgId::Length => match value_str.parse::<u64>() {
                Ok(v) => {
                    self.args.length = v;
                    self.args.length_explicit = true;
                }
                Err(e) => return Err(err_for(e.to_string())),
            },
            ArgId::Seek => match value_str.parse::<u64>() {
                Ok(v) => self.args.seek = v,
                Err(e) => return Err(err_for(e.to_string())),
            },
            ArgId::NumThreads => match value_str.parse::<usize>() {
                Ok(v) => self.args.num_threads = Some(v),
                Err(e) => return Err(err_for(e.to_string())),
            },
            _ => unreachable!(),
        }
        self.reacted[id.index()] += 1;
        Ok(())
    }

    fn react_option_occurrence(&mut self, id: ArgId, value: Option<OsString>) -> PResult<()> {
        let value = match value {
            None => return Err(self.err_missing_value(id)),
            Some(v) => v,
        };
        if self.reacted[id.index()] > 0 {
            return Err(self.err_duplicate(id));
        }
        self.validate_value(id, &value)
    }

    fn react_pending(&mut self) -> PResult<()> {
        match self.pending.take() {
            None => Ok(()),
            Some(Pending::Option { id, value }) => self.react_option_occurrence(id, value),
            Some(Pending::Files { values }) => {
                for v in &values {
                    if v.is_empty() {
                        return Err(self.err_missing_value(ArgId::File));
                    }
                }
                for v in values {
                    self.args.files.push(PathBuf::from(v));
                }
                Ok(())
            }
        }
    }

    fn flush_pending(&mut self) -> PResult<()> {
        self.react_pending()
    }

    fn react_flag(&mut self, id: ArgId) -> PResult<()> {
        if self.reacted[id.index()] > 0 {
            return Err(self.err_duplicate(id));
        }
        self.reacted[id.index()] += 1;
        self.any_flag_reacted = true;
        match id {
            ArgId::Keyed => self.args.keyed = true,
            ArgId::NoMmap => self.args.no_mmap = true,
            ArgId::NoNames => self.args.no_names = true,
            ArgId::Raw => self.args.raw = true,
            ArgId::Tag => self.args.tag = true,
