        matches!(self.pending, Some(Pending::Option { value: None, .. }))
    }

    fn set_pending_value(&mut self, token: OsString) {
        if let Some(Pending::Option { id, value }) = &mut self.pending {
            self.value_counts[id.index()] += 1;
            *value = Some(token);
        }
    }

    fn push_file(&mut self, token: OsString) -> PResult<()> {
        self.file_seen = true;
        self.record_order(ArgId::File);
        match self.pending.take() {
            Some(Pending::Files { mut values }) => {
                values.push(token);
                self.pending = Some(Pending::Files { values });
                Ok(())
            }
            Some(other) => {
                self.pending = Some(other);
                self.flush_pending()?;
                self.pending = Some(Pending::Files {
                    values: vec![token],
                });
                Ok(())
            }
            None => {
                self.pending = Some(Pending::Files {
                    values: vec![token],
                });
                Ok(())
            }
        }
    }

    fn file_marker_for_used(&self) -> &'static str {
        if self.file_seen {
            "<FILE>..."
        } else {
            "[FILE]..."
        }
    }

    fn used_options_for_unknown(&self) -> Vec<ArgId> {
        let mut used = Vec::new();
        for id in &self.order {
            if *id == ArgId::File {
                continue;
            }
            let qualified = if id.is_flag() || matches!(id, ArgId::Help | ArgId::Version) {
                self.reacted[id.index()] > 0
            } else {
                self.value_counts[id.index()] > 0
            };
            if qualified {
                used.push(*id);
            }
        }
        used
    }

    fn err_unknown_long(&self, display: String, name: &str) -> CliExit {
        let color = self.ctx.color_err;
        let sugg = suggestion(name);
        let tip = match sugg {
            Some(id) => format!(
                "{} a similar argument exists: '{}'",
                self.ctx.green(color, "tip:"),
                self.ctx
                    .green(color, &format!("--{}", id.long_name().unwrap()))
            ),
            None => format!(
                "{} to pass '{}' as a value, use '{}'",
                self.ctx.green(color, "tip:"),
                self.ctx.yellow(color, &display),
                self.ctx.green(color, &format!("-- {}", display))
            ),
        };
        let has_dup_value_occurrence = self.value_counts.iter().any(|c| *c >= 2);
        let usage = if has_dup_value_occurrence {
            self.ctx.usage_generic(color)
        } else {
            let mut used = self.used_options_for_unknown();
            if let Some(id) = sugg {
                if !used.contains(&id) {
                    used.push(id);
                }
            }
            if used.is_empty() && !self.file_seen {
                self.ctx.usage_generic(color)
            } else {
                let marker = self.file_marker_for_used();
                self.ctx.usage_list(color, &used, marker)
            }
        };
        self.ctx.error(
            format!(
                "unexpected argument '{}' found",
                self.ctx.yellow(color, &display)
            ),
            Some(tip),
            Some(usage),
        )
    }

    fn err_unknown_short(&self, display: String) -> CliExit {
        let color = self.ctx.color_err;
        let tip = format!(
            "{} to pass '{}' as a value, use '{}'",
            self.ctx.green(color, "tip:"),
            self.ctx.yellow(color, &display),
            self.ctx.green(color, &format!("-- {}", display))
        );
        self.ctx.error(
            format!(
                "unexpected argument '{}' found",
                self.ctx.yellow(color, &display)
            ),
            Some(tip),
            Some(self.ctx.usage_generic(color)),
        )
    }

    fn err_unexpected_value(&self, id: ArgId, value: &OsStr) -> CliExit {
        let color = self.ctx.color_err;
        let value_disp = String::from_utf8_lossy(value.as_bytes()).into_owned();
        let usage = if self.any_flag_reacted {
            self.ctx.usage_giant(color)
        } else {
            self.ctx.usage_list(color, &[id], "[FILE]...")
        };
        self.ctx.error(
            format!(
                "unexpected value '{}' for '{}' found; no more were expected",
                self.ctx.yellow(color, &value_disp),
                self.ctx.bold(color, id.display())
            ),
            None,
            Some(usage),
        )
    }

    fn exit_help(&self, long: bool) -> CliExit {
        CliExit {
            text: render_help(&self.ctx, long),
            code: 0,
            to_stdout: true,
        }
    }

    fn exit_version(&self) -> CliExit {
        CliExit {
            text: "b3sum 1.8.4\n".to_string(),
            code: 0,
            to_stdout: true,
        }
    }
}
EOF
echo ok"}

