enum CharDecode {
    Char(char, usize),
    Invalid,
}

fn decode_char(bytes: &[u8]) -> CharDecode {
    if bytes.is_empty() {
        return CharDecode::Invalid;
    }
    let b = bytes[0];
    if b < 0x80 {
        return CharDecode::Char(b as char, 1);
    }
    let need = if (0xc2..0xe0).contains(&b) {
        2
    } else if (0xe0..0xf0).contains(&b) {
        3
    } else if (0xf0..0xf5).contains(&b) {
        4
    } else {
        return CharDecode::Invalid;
    };
    if bytes.len() < need {
        return CharDecode::Invalid;
    }
    match std::str::from_utf8(&bytes[..need]) {
        Ok(s) => match s.chars().next() {
            Some(c) if c.len_utf8() == need => CharDecode::Char(c, need),
            _ => CharDecode::Invalid,
        },
        Err(_) => CharDecode::Invalid,
    }
}

fn long_id_from_name(name: &[u8]) -> Option<ArgId> {
    for id in OPTION_IDS {
        if id.long_name().unwrap().as_bytes() == name {
            return Some(id);
        }
    }
    None
}

impl Parser {
    fn process_long(&mut self, bytes: &[u8]) -> PResult<()> {
        // bytes begins with "--" and is longer than 2 bytes.
        let content = &bytes[2..];
        let eq = content.iter().position(|b| *b == b'=');
        let name = match eq {
            Some(p) => &content[..p],
            None => content,
        };
        let id = match long_id_from_name(name) {
            Some(id) => id,
            None => {
                let name_lossy = String::from_utf8_lossy(name).into_owned();
                let display = format!("--{}", name_lossy);
                return Err(self.err_unknown_long(display, &name_lossy));
            }
        };
        if let Some(p) = eq {
            if !id.is_value_option() {
                let value = OsStr::from_bytes(&content[p + 1..]);
                return Err(self.err_unexpected_value(id, value));
            }
            // Attached-value option.
            self.flush_pending()?;
            self.record_order(id);
            self.value_counts[id.index()] += 1;
            let value = OsString::from_vec(content[p + 1..].to_vec());
            return self.react_option_occurrence(id, Some(value));
        }
        // Proper bare form.
        self.flush_pending()?;
        self.record_order(id);
        match id {
            ArgId::Help => Err(self.exit_help(true)),
            ArgId::Version => Err(self.exit_version()),
            _ if id.is_flag() => self.react_flag(id),
            _ => {
                self.pending = Some(Pending::Option { id, value: None });
                Ok(())
            }
        }
    }

    fn process_short(&mut self, bytes: &[u8]) -> PResult<()> {
        // bytes begins with '-' and is longer than 1 byte, and does not
        // begin with "--".
        let mut idx = 1usize;
        let mut flushed_prior = false;
        while idx < bytes.len() {
            let (c, clen) = match decode_char(&bytes[idx..]) {
                CharDecode::Char(c, l) => (c, l),
                CharDecode::Invalid => {
                    let display =
                        format!("-{}", String::from_utf8_lossy(&bytes[idx..]));
                    return Err(self.err_unknown_short(display));
                }
            };
            let known = matches!(c, 'l' | 'c' | 'h' | 'V');
            if !known {
                return Err(self.err_unknown_short(format!("-{}", c)));
            }
            if !flushed_prior {
                self.flush_pending()?;
                flushed_prior = true;
            }
            match c {
                'c' => {
                    self.record_order(ArgId::Check);
                    self.react_flag(ArgId::Check)?;
                    idx += clen;
                }
                'h' => return Err(self.exit_help(false)),
                'V' => return Err(self.exit_version()),
                'l' => {
                    self.record_order(ArgId::Length);
                    let rest = &bytes[idx + clen..];
                    if rest.is_empty() {
                        self.pending = Some(Pending::Option {
                            id: ArgId::Length,
                            value: None,
                        });
                    } else {
                        let raw: &[u8] = if rest[0] == b'=' { &rest[1..] } else { rest };
                        self.value_counts[ArgId::Length.index()] += 1;
                        let value = OsString::from_vec(raw.to_vec());
                        self.react_option_occurrence(ArgId::Length, Some(value))?;
                    }
                    idx = bytes.len();
                }
                _ => unreachable!(),
            }
        }
        Ok(())
    }

    fn conflicts_with(a: ArgId, b: ArgId) -> bool {
        use ArgId::*;
        let pair = if a.index() < b.index() { (a, b) } else { (b, a) };
        matches!(
            pair,
            (Keyed, DeriveKey)
                | (Keyed, Check)
                | (DeriveKey, Check)
                | (Length, Check)
                | (NoNames, Check)
                | (Raw, Check)
                | (Tag, Check)
        )
    }

    fn validate_conflicts(&self) -> PResult<()> {
        let color = self.ctx.color_err;
        let present: Vec<ArgId> = self
            .order
            .iter()
            .cloned()
            .filter(|id| *id != ArgId::File && self.reacted[id.index()] > 0)
            .collect();
        for subject in &present {
            let objects: Vec<ArgId> = present
                .iter()
                .cloned()
                .filter(|id| *id != *subject && Self::conflicts_with(*subject, *id))
                .collect();
            if objects.is_empty() {
                continue;
            }
            let msg = if objects.len() == 1 {
                format!(
                    "the argument '{}' cannot be used with '{}'",
                    self.ctx.yellow(color, subject.display()),
                    self.ctx.yellow(color, objects[0].display())
                )
            } else {
                let mut m = format!(
                    "the argument '{}' cannot be used with:",
                    self.ctx.yellow(color, subject.display())
                );
                for obj in &objects {
                    m.push_str(&format!("\n  {}", self.ctx.yellow(color, obj.display())));
                }
                m
            };
            let usage_options: Vec<ArgId> = present
                .iter()
                .cloned()
                .filter(|id| !objects.contains(id))
                .collect();
            let marker = if !self.args.files.is_empty()
                || usage_options.contains(&ArgId::Keyed)
            {
                "<FILE>..."
            } else {
                "[FILE]..."
            };
            let usage = self.ctx.usage_list(color, &usage_options, marker);
            return Err(self.ctx.error(msg, None, Some(usage)));
        }
        Ok(())
    }

    fn validate_required(&self) -> PResult<()> {
        let color = self.ctx.color_err;
        let file_missing = self.args.keyed && self.args.files.is_empty();
        let conflicts_check_present = self.args.keyed
            || self.args.derive_key.is_some()
            || self.args.length_explicit
            || self.args.no_names
            || self.args.raw
            || self.args.tag;
        let mut missing: Vec<ArgId> = Vec::new();
        if self.args.quiet && !self.args.check {
            if file_missing || !conflicts_check_present {
                missing.push(ArgId::Check);
            }
        }
        if file_missing {
            missing.push(ArgId::File);
        }
        if missing.is_empty() {
            return Ok(());
        }
        let mut msg = "the following required arguments were not provided:".to_string();
        for id in &missing {
            let disp = if *id == ArgId::File {
                "<FILE>..."
            } else {
                id.display()
            };
            msg.push_str(&format!("\n  {}", self.ctx.green(color, disp)));
        }
        let mut usage_options: Vec<ArgId> = Vec::new();
        for id in &missing {
            if *id != ArgId::File {
                usage_options.push(*id);
            }
        }
        for id in &self.order {
            if *id != ArgId::File && self.reacted[id.index()] > 0 {
                usage_options.push(*id);
            }
        }
        let marker = if !self.args.files.is_empty() || missing.contains(&ArgId::File) {
            "<FILE>..."
        } else {
            "[FILE]..."
        };
        let usage = self.ctx.usage_list(color, &usage_options, marker);
        Err(self.ctx.error(msg, None, Some(usage)))
    }

    fn parse_tokens(mut self, tokens: Vec<OsString>) -> ParseOutcome {
        let run = (|| -> PResult<()> {
            let mut i = 0usize;
            while i < tokens.len() {
                let token = tokens[i].clone();
                i += 1;
                let bytes: Vec<u8> = token.as_os_str().as_bytes().to_vec();
                if self.after_sep {
                    self.push_file(token)?;
                    continue;
                }
                if bytes == b"--" {
                    self.flush_pending()?;
                    self.after_sep = true;
                    continue;
                }
                if self.pending_expecting() {
                    let is_value =
                        bytes == b"-" || bytes.first().map(|b| *b != b'-').unwrap_or(true);
                    if is_value {
                        self.set_pending_value(token);
                        continue;
                    }
                }
                if bytes.len() > 2 && bytes.starts_with(b"--") {
                    self.process_long(&bytes)?;
                    continue;
                }
                if bytes.len() > 1 && bytes.starts_with(b"-") && !bytes.starts_with(b"--") {
                    self.process_short(&bytes)?;
                    continue;
                }
                // A plain "-" and anything not starting with '-' (or an
                // empty token) is a positional value here.
                self.push_file(token)?;
            }
            self.flush_pending()?;
            self.validate_conflicts()?;
            self.validate_required()?;
            Ok(())
        })();
        match run {
            Ok(()) => ParseOutcome::Args(self.args),
            Err(e) => ParseOutcome::Exit(e),
        }
    }
}

fn bin_name(argv0: Option<&OsString>) -> String {
    if let Some(os) = argv0 {
        if let Some(s) = os.to_str() {
            if let Some(name) = Path::new(s).file_name() {
                if let Some(n) = name.to_str() {
                    if !n.is_empty() {
                        return n.to_string();
                    }
                }
            }
        }
    }
    "b3sum".to_string()
}

pub fn parse_args() -> ParseOutcome {
    let mut iter = env::args_os();
    let argv0 = iter.next();
    let context = Ctx {
        bin: bin_name(argv0.as_ref()),
        width: terminal_width(),
        color_out: color_enabled(io::stdout().is_terminal()),
        color_err: color_enabled(io::stderr().is_terminal()),
    };
    let tokens: Vec<OsString> = iter.collect();
    Parser::new(context).parse_tokens(tokens)
}
