                        self.set_pending_value(token);
                        continue;
                    }
                }
                if bytes.len() > 2 && bytes.starts_with(b"--") {
                    self.process_long(&bytes)?;
                    continue;
                }
                if bytes.len() > 1 && bytes.starts_with(b"-") && !bytes.starts_with(b"--") {
                    self.process_short(&bytes)?;
                    continue;
                }
                // A plain "-" and anything not starting with '-' (or an
                // empty token) is a positional value here.
                self.push_file(token)?;
            }
            self.flush_pending()?;
            self.validate_conflicts()?;
            self.validate_required()?;
            Ok(())
        })();
        match run {
            Ok(()) => ParseOutcome::Args(self.args),
            Err(e) => ParseOutcome::Exit(e),
        }
    }
}

fn bin_name(argv0: Option<&OsString>) -> String {
    if let Some(os) = argv0 {
        if let Some(s) = os.to_str() {
            if let Some(name) = Path::new(s).file_name() {
                if let Some(n) = name.to_str() {
                    if !n.is_empty() {
                        return n.to_string();
                    }
                }
            }
        }
    }
    "b3sum".to_string()
}

pub fn parse_args() -> ParseOutcome {
    let mut iter = env::args_os();
    let argv0 = iter.next();
    let context = Ctx {
        bin: bin_name(argv0.as_ref()),
        width: terminal_width(),
        color_out: color_enabled(io::stdout().is_terminal()),
        color_err: color_enabled(io::stderr().is_terminal()),
    };
    let tokens: Vec<OsString> = iter.collect();
    Parser::new(context).parse_tokens(tokens)
}
