mod blake3;
mod cli;

use std::fmt;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use blake3::{Hasher, Output};
use cli::{ParsedArgs, ParseOutcome};

pub struct TopError(String);

impl fmt::Debug for TopError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

fn main() -> Result<ExitCode, TopError> {
    // Run the real work on an unnamed spawned thread, re-raising any
    // panic in the main thread.  This keeps the process behaviour for
    // failed `println!` writes (for example a broken pipe) consistent
    // with a program whose work does not happen on the main thread:
    // the panic is reported once, from the worker, and the process
    // exits with the usual Rust panic status.
    let handle = std::thread::spawn(real_main);
    match handle.join() {
        Ok(result) => result,
        Err(payload) => std::panic::resume_unwind(payload),
    }
}

fn real_main() -> Result<ExitCode, TopError> {
    let args = match cli::parse_args() {
        ParseOutcome::Args(a) => a,
        ParseOutcome::Exit(e) => cli::handle_exit(e),
    };
    if args.check {
        check_main(&args)
    } else {
        hash_main(&args)
    }
}

// ---------------- hashing mode ----------------

fn path_display_lossy(path: &Path) -> String {
    path.to_string_lossy().into_owned()
}

fn escape_path(path_str: &str) -> (bool, String) {
    let mut needs = false;
    let mut out = String::with_capacity(path_str.len());
    for c in path_str.chars() {
        match c {
            '\\' => {
                needs = true;
                out.push_str("\\\\");
            }
            '\n' => {
                needs = true;
                out.push_str("\\n");
            }
            '\r' => {
                needs = true;
                out.push_str("\\r");
            }
            _ => out.push(c),
        }
    }
    (needs, out)
}

enum FileHashError {
    Io(io::Error),
    KeyedDash,
}

impl fmt::Display for FileHashError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            FileHashError::Io(e) => write!(f, "{}", e),
            FileHashError::KeyedDash => write!(f, "Cannot open `-` in keyed mode"),
        }
    }
}

fn is_dash(path: &Path) -> bool {
    path.as_os_str() == "-"
}

fn hash_path(
    path: &Path,
    template: &Hasher,
    keyed: bool,
) -> Result<Output, FileHashError> {
    let mut hasher = template.clone();
    if is_dash(path) {
        if keyed {
            return Err(FileHashError::KeyedDash);
        }
        let mut stdin = io::stdin().lock();
        hasher
            .update_reader(&mut stdin)
            .map_err(FileHashError::Io)?;
    } else {
        let mut file = File::open(path).map_err(FileHashError::Io)?;
        hasher
            .update_reader(&mut file)
            .map_err(FileHashError::Io)?;
    }
    Ok(hasher.finalize_output())
}

fn read_key() -> Result<[u8; 32], TopError> {
    let mut stdin = io::stdin().lock();
    let mut buf = [0u8; 33];
    let mut filled = 0usize;
    while filled < buf.len() {
        match stdin.read(&mut buf[filled..]) {
            Ok(0) => break,
            Ok(n) => filled += n,
            Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(TopError(e.to_string())),
        }
    }
    if filled > 32 {
        return Err(TopError(
            "read more than 32 key bytes from stdin".to_string(),
        ));
    }
    if filled < 32 {
        return Err(TopError(format!(
            "expected 32 key bytes from stdin, found {}",
            filled
        )));
    }
    let mut key = [0u8; 32];
    key.copy_from_slice(&buf[..32]);
    Ok(key)
}

fn hex_encode_into(out: &mut String, bytes: &[u8]) {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    out.reserve(bytes.len() * 2);
    for b in bytes {
        out.push(HEX[(b >> 4) as usize] as char);
        out.push(HEX[(b & 0xf) as usize] as char);
    }
}

fn print_hex_output(output: &Output, args: &ParsedArgs, path_str: &str) {
    let (needs_escape, escaped) = escape_path(path_str);
    if !args.no_names && args.tag {
        if needs_escape {
            print!("\\");
        }
        print!("BLAKE3 ({}) = ", escaped);
    } else if !args.no_names && needs_escape {
        print!("\\");
    }

    // Stream the extended output in blocks so that arbitrarily large
    // --length values do not need an output-sized allocation.
    let mut reader = output.xof_reader(args.seek);
    let mut remaining = args.length;
    let mut block = [0u8; 8192];
    let mut hex = String::new();
    while remaining > 0 {
        let want = remaining.min(block.len() as u64) as usize;
        // The XOF reader never reaches EOF.
        let _ = reader.read_exact(&mut block[..want]);
        hex.clear();
        hex_encode_into(&mut hex, &block[..want]);
        print!("{}", hex);
        remaining -= want as u64;
    }

    if args.no_names || args.tag {
        println!();
    } else {
        println!("  {}", escaped);
    }
}

fn write_raw_output(
    output: &Output,
    args: &ParsedArgs,
    path: &Path,
) -> Result<(), FileHashError> {
    let mut stdout = io::stdout().lock();
    let mut reader = output.xof_reader(args.seek).take(args.length);
    io::copy(&mut reader, &mut stdout).map_err(|e| {
        let _ = path;
        FileHashError::Io(e)
    })?;
    Ok(())
}

fn hash_main(args: &ParsedArgs) -> Result<ExitCode, TopError> {
    if args.raw && args.files.len() > 1 {
        return Err(TopError(
            "Only one filename can be provided when using --raw".to_string(),
        ));
    }

    let template = if args.keyed {
        let key = read_key()?;
        Hasher::new_keyed(&key)
    } else if let Some(context) = &args.derive_key {
        Hasher::new_derive_key(context)
    } else {
        Hasher::new()
    };

    let default_files: Vec<PathBuf>;
    let files: &[PathBuf] = if args.files.is_empty() {
        default_files = vec![PathBuf::from("-")];
        &default_files
    } else {
        &args.files
    };

    let mut failed = false;
    for path in files {
        match hash_path(path, &template, args.keyed) {
            Ok(output) => {
                if args.raw {
                    if let Err(e) = write_raw_output(&output, args, path) {
                        eprintln!("b3sum: {}: {}", path_display_lossy(path), e);
                        failed = true;
                    }
                } else {
                    let displayed = path_display_lossy(path);
                    print_hex_output(&output, args, &displayed);
                }
            }
            Err(e) => {
                eprintln!("b3sum: {}: {}", path_display_lossy(path), e);
                failed = true;
            }
        }
    }
    Ok(ExitCode::from(if failed { 1 } else { 0 }))
}

// ---------------- check mode ----------------

enum CheckError {
    EmptyLine,
    InvalidFormat,
    InvalidHashLength,
    InvalidHex,
    EmptyPath,
    InvalidEscape,
    NullInPath,
}

impl CheckError {
    fn message(&self) -> &'static str {
        match self {
            CheckError::EmptyLine => "Empty line",
            CheckError::InvalidFormat => "Invalid check line format",
            CheckError::InvalidHashLength => "Invalid hash length",
            CheckError::InvalidHex => "Invalid hex",
            CheckError::EmptyPath => "empty file path",
            CheckError::InvalidEscape => "Invalid backslash escape",
            CheckError::NullInPath => "Null character in path",
        }
    }
}

struct ParsedLine {
    expected: [u8; 32],
    path: String,
    display: String,
}

fn unescape_path(token: &str) -> Result<String, CheckError> {
    let mut out = String::with_capacity(token.len());
    let mut chars = token.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        match chars.next() {
            Some('n') => out.push('\n'),
            Some('r') => out.push('\r'),
            Some('\\') => out.push('\\'),
            _ => return Err(CheckError::InvalidEscape),
        }
    }
    Ok(out)
}

fn parse_hex_hash(s: &str) -> Result<[u8; 32], CheckError> {
    if s.len() != 64 {
        return Err(CheckError::InvalidHashLength);
    }
    let bytes = s.as_bytes();
    let mut out = [0u8; 32];
    for i in 0..32 {
        let hi = bytes[i * 2];
        let lo = bytes[i * 2 + 1];
        let hv = |b: u8| -> Result<u8, CheckError> {
            match b {
                b'0'..=b'9' => Ok(b - b'0'),
                b'a'..=b'f' => Ok(b - b'a' + 10),
                _ => Err(CheckError::InvalidHex),
            }
        };
        out[i] = (hv(hi)? << 4) | hv(lo)?;
    }
    Ok(out)
}

fn parse_check_line(raw_line: &str) -> Result<ParsedLine, CheckError> {
    let line = raw_line.trim_end_matches('\r');
    if line.is_empty() {
        return Err(CheckError::EmptyLine);
    }
    let (escaped, rest) = match line.strip_prefix('\\') {
        Some(r) => (true, r),
        None => (false, line),
    };

    let (hash_hex, path_token): (&str, &str) = if let Some((h, p)) = rest.split_once("  ") {
        (h, p)
    } else if let Some(after) = rest.strip_prefix("BLAKE3 (") {
        match after.rsplit_once(") = ") {
            Some((p, h)) => (h, p),
            None => return Err(CheckError::InvalidFormat),
        }
    } else {
        return Err(CheckError::InvalidFormat);
    };

    let expected = parse_hex_hash(hash_hex)?;

    if path_token.is_empty() {
        return Err(CheckError::EmptyPath);
    }
    let path = if escaped {
        unescape_path(path_token)?
    } else {
        path_token.to_string()
    };
    if path.contains('\0') {
        return Err(CheckError::NullInPath);
    }
    if path.is_empty() {
        return Err(CheckError::EmptyPath);
    }

    let display = if escaped {
        format!("\\{}", path_token)
    } else {
        path_token.to_string()
    };

    Ok(ParsedLine {
        expected,
        path,
        display,
    })
}

enum CheckLineIter {
    Stdin(io::Lines<io::StdinLock<'static>>),
    File(io::Lines<BufReader<File>>),
}

impl CheckLineIter {
    fn next_line(&mut self) -> Option<io::Result<String>> {
        match self {
            CheckLineIter::Stdin(it) => it.next(),
            CheckLineIter::File(it) => it.next(),
        }
    }
}

fn open_checkfile(path: &Path) -> Result<CheckLineIter, TopError> {
    if is_dash(path) {
        Ok(CheckLineIter::Stdin(io::stdin().lock().lines()))
    } else {
        let file = File::open(path).map_err(|e| TopError(e.to_string()))?;
        Ok(CheckLineIter::File(BufReader::new(file).lines()))
    }
}

fn check_main(args: &ParsedArgs) -> Result<ExitCode, TopError> {
    let template = Hasher::new();

    let default_files: Vec<PathBuf>;
    let files: &[PathBuf] = if args.files.is_empty() {
        default_files = vec![PathBuf::from("-")];
        &default_files
    } else {
        &args.files
    };

