        return Err(CheckError::EmptyPath);
    }
    let path = if escaped {
        unescape_path(path_token)?
    } else {
        path_token.to_string()
    };
    if path.contains('\0') {
        return Err(CheckError::NullInPath);
    }
    if path.is_empty() {
        return Err(CheckError::EmptyPath);
    }

