import os,pty,subprocess,select,fcntl,termios,struct
def run(exe,args,cols,env,stdout_pty=True,stderr_pty=True,stdin_pty=False):
    masters={}; slaves={}
    def make(name):
        m,s=pty.openpty(); fcntl.ioctl(s,termios.TIOCSWINSZ,struct.pack('HHHH',24,cols,0,0)); masters[name]=m; slaves[name]=s; return s
    stdin = make('stdin') if stdin_pty else subprocess.PIPE
    stdout = make('stdout') if stdout_pty else subprocess.PIPE
    stderr = make('stderr') if stderr_pty else subprocess.PIPE
    e={k:v for k,v in os.environ.items() if k not in ('COLUMNS','TERM','NO_COLOR','CLICOLOR','CLICOLOR_FORCE')}; e.update(env)
    p=subprocess.Popen([exe]+args,stdin=stdin,stdout=stdout,stderr=stderr,env=e,cwd='/tmp/t2')
    for s in slaves.values(): os.close(s)
    if not stdin_pty:
        try:p.stdin.write(b'hello');p.stdin.close()
        except:pass
    outs={}
    p.wait()
    for name,m in masters.items():
        data=b''
        while True:
            try:d=os.read(m,65536)
            except:break
            if not d:break
            data+=d
        outs[name]=data;os.close(m)
    if not stdout_pty:outs['stdout']=p.stdout.read()
    if not stderr_pty:outs['stderr']=p.stderr.read()
    return p.returncode,outs
